<?php
session_start();
require_once __DIR__.'/../backend/db.php';
require_once __DIR__.'/../backend/management_organization_helper.php';
$account = !empty($_SESSION['user_id']) ? synk_find_useraccount_by_id($conn,(int)$_SESSION['user_id']) : null;
if (($_SESSION['role'] ?? '')!=='admin' || !$account || ($account['status'] ?? '')!=='active' || !synk_useraccount_has_active_role($conn,$account,'admin')) { header('Location: ../index.php'); exit; }
header('Cache-Control: no-store, private');
if (empty($_SESSION['csrf_token'])) $_SESSION['csrf_token']=bin2hex(random_bytes(32));
$colleges=synk_management_query($conn,"SELECT c.college_id,c.college_code,c.college_name,c.status,c.campus_id,p.campus_name,p.status AS campus_status FROM tbl_college c JOIN tbl_campus p ON p.campus_id=c.campus_id ORDER BY p.campus_name,c.college_code");
$campuses=synk_management_query($conn,'SELECT campus_id,campus_name,status FROM tbl_campus ORDER BY campus_name');
try {
    foreach (['search','campus_id','college_id','page'] as $key) if (isset($_GET[$key]) && !is_string($_GET[$key])) throw new DomainException('Choose valid filters.');
    $search=trim((string)($_GET['search'] ?? ''));
    if (mb_strlen($search,'UTF-8')>150 || !preg_match('//u',$search)) throw new DomainException('Search using up to 150 characters.');
    $campus=synk_management_input_id($_GET['campus_id'] ?? '',true); $college=synk_management_input_id($_GET['college_id'] ?? '',true);
    $page=filter_var($_GET['page'] ?? 1,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);
    if (!$page) throw new DomainException('Choose a valid page.');
    $where=' FROM tbl_management_organizations o JOIN tbl_college c ON c.college_id=o.college_id JOIN tbl_campus p ON p.campus_id=c.campus_id WHERE 1=1'; $types=''; $values=[];
    if ($campus) { $where.=' AND c.campus_id=?'; $types.='i'; $values[]=$campus; }
    if ($college) { $where.=' AND c.college_id=?'; $types.='i'; $values[]=$college; }
    if ($search!=='') { $where.=" AND CONCAT_WS(' ',o.organization_code,o.organization_name) LIKE ? ESCAPE '!'"; $types.='s'; $values[]='%'.str_replace(['!','%','_'],['!!','!%','!_'],$search).'%'; }
    $total=(int)synk_management_query($conn,'SELECT COUNT(*) AS n'.$where,$types,$values)[0]['n']; $pages=max(1,(int)ceil($total/25)); $page=min($page,$pages);
    $rows=synk_management_query($conn,'SELECT o.*,c.college_code,p.campus_name,(SELECT COUNT(*) FROM tbl_useraccount u WHERE u.management_organization_id=o.organization_id) AS accounts'.$where.' ORDER BY p.campus_name,c.college_code,o.organization_code LIMIT 25 OFFSET ?',$types.'i',array_merge($values,[($page-1)*25]));
} catch (DomainException $e) { http_response_code(400); exit(synk_management_h($e->getMessage())); }
$h='synk_management_h';
?>
